function readEnv(name, fallback = '') {
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return $env[name];
  } catch (error) {}
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return $vars[name];
  } catch (error) {}
  try {
    const processModule = require('process');
    if (processModule.env && processModule.env[name]) return processModule.env[name];
  } catch (error) {}
  try {
    if (typeof process !== 'undefined' && process.env && process.env[name]) return process.env[name];
  } catch (error) {}
  return fallback;
}

const crypto = require('crypto');

const expectedEvent = 'scan.completed';
const input = $input.first().json;
const headersInput = input.headers || {};
const headers = {};

for (const [key, value] of Object.entries(headersInput)) {
  headers[String(key).toLowerCase()] = Array.isArray(value) ? String(value[0]) : String(value);
}

function reject(message) {
  const error = new Error(message);
  error.name = 'SideraScanWebhookRejected';
  throw error;
}

const timestamp = headers['x-siderascan-timestamp'];
const signature = headers['x-siderascan-signature'];
const idempotencyKey = headers['x-idempotency-key'];
const eventHeader = headers['x-siderascan-event'];
const body = input.body || {};

if (!timestamp || !signature || !idempotencyKey) reject('Missing required SideraScan webhook headers.');
if (eventHeader && eventHeader !== expectedEvent) reject('Unexpected SideraScan event: ' + eventHeader);
if (body.event && body.event !== expectedEvent) reject('Unexpected body event: ' + body.event);
if (!/^sha256=[a-f0-9]{64}$/i.test(signature)) reject('Invalid SideraScan signature format.');

const unixSeconds = Number(timestamp);
if (!Number.isFinite(unixSeconds)) reject('Invalid SideraScan timestamp.');

const tolerance = Number(readEnv('SIDERASCAN_SIGNATURE_TOLERANCE_SECONDS', '300'));
const ageSeconds = Math.abs(Date.now() / 1000 - unixSeconds);
if (ageSeconds > tolerance) reject('Expired SideraScan signature.');

const secret = readEnv('SIDERASCAN_WEBHOOK_SECRET');
if (!secret || secret.includes('<')) reject('SideraScan webhook secret is not configured in n8n.');

const signedBody = JSON.stringify(body ?? {});
const expectedSignature = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(timestamp + '.' + signedBody)
  .digest('hex');

const providedBuffer = Buffer.from(signature);
const expectedBuffer = Buffer.from(expectedSignature);
if (providedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(providedBuffer, expectedBuffer)) reject('Invalid SideraScan signature.');

return [{ json: { response: { status: 'accepted', event: expectedEvent, idempotencyKey }, request: { body, idempotencyKey, event: expectedEvent } } }];

