const crypto = require('crypto');

const input = $input.first().json;
const body = input.request?.body || {};
const scanSessionId = body.scanSessionId || body.scanId;
if (!scanSessionId || typeof scanSessionId !== 'string') throw new Error('scanSessionId or scanId is required for AI review.');

const provider = (readEnv('AI_PROVIDER', 'gemini')).toLowerCase();
if (provider !== 'gemini') throw new Error('Unsupported AI_PROVIDER for this workflow template: ' + provider);

function take(value, fallback = null) { return value === undefined || value === null ? fallback : value; }
function safeObject(value) { return value && typeof value === 'object' && !Array.isArray(value) ? value : {}; }
function safeArray(value, max = 50) { return Array.isArray(value) ? value.slice(0, max) : []; }

const normalized = {
  scanSessionId,
  account: { id: take(body.accountId), name: take(body.accountName) },
  playerLabel: take(body.playerLabel),
  risk: { score: take(body.riskScore, 0), severity: take(body.severity, 'INFO'), findingSeverityCounts: safeObject(body.findingSeverityCounts) },
  counts: { findingCount: take(body.findingCount, 0), evidenceCount: take(body.evidenceCount, 0) },
  scanner: { version: take(body.scannerVersion) },
  device: safeObject(body.device),
  forensicSummary: safeObject(body.forensicSummary),
  reviewContext: safeObject(body.reviewContext),
  dashboardUrl: take(body.dashboardUrl),
  topFindings: safeArray(body.topFindings, 20),
  evidenceReferences: safeArray(body.evidenceReferences, 30),
  keyIndicators: safeArray(body.keyIndicators, 30),
  generatedFrom: 'siderascan-redacted-scan-completed-event'
};

const inputHash = crypto.createHash('sha256').update(JSON.stringify(normalized)).digest('hex');
return [{ json: { idempotencyKey: input.request?.idempotencyKey, provider, model: readEnv('GEMINI_MODEL', 'gemini-3.6-flash'), promptVersion: readEnv('SIDERASCAN_AI_PROMPT_VERSION', 'n8n-ai-review-v2'), sideraScanApiBaseUrl: readEnv('SIDERASCAN_API_BASE_URL', 'http://host.docker.internal:4000'), normalized, inputHash } }];

