const input = $input.first().json;
const schemaDescription = {
  scanSessionId: 'string UUID from SideraScan payload',
  assessment: 'short string, max 80 chars. Mention the dominant review theme, not a final verdict.',
  confidence: 'integer 0-100',
  summaryForModerator: 'moderator-facing advisory summary. Include a short chronological timeline when reviewContext.recentTimeline exists, mention active/open process context when reviewContext.activeProcesses exists, and distinguish historical artifacts from active runtime signals.',
  summaryForPlayer: 'optional neutral player-facing explanation, max 5000 chars',
  recommendedAction: 'one of NO_ACTION, MONITOR, REQUEST_RESCAN, MANUAL_REVIEW, ESCALATE',
  keyIndicators: 'array of short strings. Prefer concrete findings/processes/timeline events from topFindings/reviewContext.',
  possibleFalsePositives: 'array of short strings. Include benign explanations for historical installers, normal signed drivers, overlays, and context-only artifacts.',
  contradictions: 'array of short strings. Mention weak evidence, old timestamps, missing active correlation, or low risk score where applicable.',
  moderatorChecklist: 'array of actionable checklist strings. Include timeline correlation, active process verification, and evidence-reference checks when data exists.',
  questionsForPlayer: 'array of short strings',
  evidenceReferences: 'array of { findingId?, evidenceId?, label?, note? } using only IDs/labels present in topFindings/evidenceReferences',
  model: 'model id',
  promptVersion: 'prompt version',
  generatedAt: 'ISO timestamp',
  inputHash: 'sha256 hash of normalized redacted input'
};
const prompt = [
  'You are an advisory anti-cheat scan reviewer for SideraScan.',
  'You only review redacted metadata prepared by the SideraScan backend. Do not claim certainty beyond the evidence.',
  'Never recommend AUTO_BAN, direct ban, punishment, HWID mark, or any final automated action.',
  'Allowed recommendedAction values: NO_ACTION, MONITOR, REQUEST_RESCAN, MANUAL_REVIEW, ESCALATE.',
  'Prefer MANUAL_REVIEW or ESCALATE for serious concerns. Use NO_ACTION or MONITOR when evidence is weak/context-only.',
  'Treat forensic signals as advisory. Multiple supporting signals are stronger than one filename or one historical artifact.',
  'If reviewContext.recentTimeline exists, summarize the strongest 3-6 chronological events with timestamps or relative ordering.',
  'If reviewContext.activeProcesses exists, mention notable active/open applications only when relevant to the scan conclusion.',
  'Do not imply old Prefetch/Downloads/Recent/JumpList timestamps prove activity during the protected scan unless correlated with active process/game timeline.',
  'Use evidenceReferences only from topFindings/evidenceReferences. Do not invent evidence IDs.',
  'Return JSON only. No markdown, no code fences.',
  'Required JSON schema description:', JSON.stringify(schemaDescription),
  'Redacted scan context:', JSON.stringify(input.normalized)
].join('\n\n');
const geminiRequest = { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { temperature: 0.15, maxOutputTokens: 6144, responseMimeType: 'application/json' } };
return [{ json: { ...input, prompt, geminiUrl: 'https://generativelanguage.googleapis.com/v1beta/models/' + encodeURIComponent(input.model) + ':generateContent', geminiRequest } }];

function readEnv(name, fallback = '') {
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return $env[name];
  } catch (error) {}
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return $vars[name];
