function getContext() { try { return $('Build AI review prompt').first().json; } catch (error) { return {}; } }
const response = $input.first().json;
const context = getContext();
function fail(message) { const error = new Error(message); error.name = 'SideraScanAIReviewRejected'; throw error; }
function truncate(value, max) { if (value === undefined || value === null) return undefined; return String(value).slice(0, max); }
function stringArray(value, maxItems = 30, maxLen = 500) {
  if (!Array.isArray(value)) return [];
  return value.slice(0, maxItems).map((item) => {
    if (typeof item === 'string') return truncate(item, maxLen);
    if (item && typeof item === 'object') return truncate(item.item || item.text || item.label || JSON.stringify(item), maxLen);
    return truncate(item, maxLen);
  }).filter(Boolean);
}
function parseJSONText(text) {
  let trimmed = String(text || '').trim();
  if (!trimmed) fail('Gemini returned an empty response.');
  const fence = String.fromCharCode(96, 96, 96);
  if (trimmed.toLowerCase().startsWith(fence + 'json')) trimmed = trimmed.slice(7).trim();
  else if (trimmed.startsWith(fence)) trimmed = trimmed.slice(3).trim();
  if (trimmed.endsWith(fence)) trimmed = trimmed.slice(0, -3).trim();
  try { return JSON.parse(trimmed); } catch (error) { fail('Gemini returned malformed JSON.'); }
}
const parts = response.candidates?.[0]?.content?.parts || [];
const text = parts.map((part) => part.text || '').join('').trim();
const ai = parseJSONText(text);
const allowedActions = new Set(['NO_ACTION', 'MONITOR', 'REQUEST_RESCAN', 'MANUAL_REVIEW', 'ESCALATE']);
const recommendedAction = String(ai.recommendedAction || '').toUpperCase();
if (!allowedActions.has(recommendedAction)) fail('Gemini recommended an unsupported action.');
const combinedText = JSON.stringify(ai).toLowerCase();
if (/auto[-s]?ban|automatic ban|ban immediately|permanent ban|issue ban|apply ban|hwid ban|hardware ban/.test(combinedText)) fail('Gemini output attempted a final ban or punishment action.');
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const evidenceReferences = Array.isArray(ai.evidenceReferences) ? ai.evidenceReferences.slice(0, 30).map((ref) => {
  const row = {};
  if (ref && typeof ref === 'object') {
    if (typeof ref.findingId === 'string' && uuidPattern.test(ref.findingId)) row.findingId = ref.findingId;
    if (typeof ref.evidenceId === 'string' && uuidPattern.test(ref.evidenceId)) row.evidenceId = ref.evidenceId;
    if (ref.label) row.label = truncate(ref.label, 160);
    if (ref.note) row.note = truncate(ref.note, 500);
  }
  return Object.keys(row).length > 0 ? row : null;
}).filter(Boolean) : [];
const scanSessionId = context.normalized?.scanSessionId || ai.scanSessionId;
if (!scanSessionId || !uuidPattern.test(scanSessionId)) fail('scanSessionId must be a valid UUID for SideraScan callback.');
const review = {
  scanSessionId,
  assessment: truncate(ai.assessment || 'AI advisory review', 80),
  confidence: Math.max(0, Math.min(100, Math.round(Number(ai.confidence ?? 50)))),
  summaryForModerator: truncate(ai.summaryForModerator || 'AI review completed with limited detail.', 5000),
  summaryForPlayer: truncate(ai.summaryForPlayer || '', 5000),
  recommendedAction,
  keyIndicators: stringArray(ai.keyIndicators),
  possibleFalsePositives: stringArray(ai.possibleFalsePositives),
  contradictions: stringArray(ai.contradictions),
  moderatorChecklist: stringArray(ai.moderatorChecklist),
  questionsForPlayer: stringArray(ai.questionsForPlayer),
  evidenceReferences,
  model: truncate(context.model || ai.model || 'gemini', 120),
  promptVersion: truncate(context.promptVersion || ai.promptVersion || 'n8n-ai-review-v1', 80),
  inputHash: truncate(context.inputHash || ai.inputHash, 128),
  generatedAt: new Date(ai.generatedAt || Date.now()).toISOString()
};
return [{ json: { review, callbackUrl: (context.sideraScanApiBaseUrl || 'http://host.docker.internal:4000') + '/scan-reviews', callbackEvent: 'scan.reviewed', callbackIdempotencyKey: 'scan.reviewed:' + review.scanSessionId + ':' + String(review.inputHash || '').slice(0, 16) } }];

